{"command": "cd /home/zhouhuijuan1987/wiki-openclaw/youtube-video-research-wiki && python3 -c "
import re, glob
e = {f.replace('wiki/','').rsplit('.md',1)[0].lower() for f in glob.glob('wiki/**/*.md', recursive=True)}
d = 0
for f in glob.glob('wiki/**/*.md', recursive=True):
    content = open(f).read()
    for l in re.findall(r'\[\[([^\]]+?)(?:\|[^\]]+)?\]\]', content):
        target = l.strip().lower()
        if not any(target == s or target == s.split('/')[-1] for s in e):
            print(f'DEAD: {f}: [[{l.strip()}]]')
            d += 1
print('OK' if d == 0 else f'{d} DEAD')
"", "timeout": 15}

