import glob
err = False
for f in glob.glob('wiki/**/*.md', recursive=True):
    with open(f) as fh:
        lines = fh.readlines()
    for i, line in enumerate(lines):
        if line.startswith('sources:') and '[[' in line:
            print(f'P5b ❌ {f}:{i+1} {line.strip()[:80]}')
            err = True
        if line.startswith('tags:') and '[[' in line:
            print(f'P5b ❌ {f}:{i+1} {line.strip()[:80]}')
            err = True
if not err:
    print('P5b ✅ No wikilink pollution in sources/tags')
